on conflict (user_id) do update set
  display_name = excluded.display_name, bridgeys = excluded.bridgeys, completed_skills = excluded.completed_skills,
  best_furniture_value = excluded.best_furniture_value, best_furniture_name = excluded.best_furniture_name,
  equipped_title = excluded.equipped_title, house_style = excluded.house_style, avatar = excluded.avatar,
  updated_at = excluded.updated_at
where leaderboard_stats.updated_at < excluded.updated_at;

-- Check: every student with progress has a row, and no row is behind.
select count(*) filter (where ls.user_id is null) as missing,
       count(*) filter (where up.updated_at > ls.updated_at + interval '1 hour') as stale
from public.user_progress up left join public.leaderboard_stats ls using (user_id);
